#include <iostream>
#include <optional>
#include <vector>

std::optional<int> SecondLargest(const std::vector<int>& values);

int main()
{
    int n;
    while (std::cin >> n)
    {
        std::vector<int> values(n);
        for (int i = 0; i < n; i++)
        {
            std::cin >> values[i];
        }
        std::optional<int> r = SecondLargest(values);
        if (r) { std::cout << *r << "\n"; }
        else   { std::cout << "none\n"; }
    }
    return 0;
}

