"""Random small-range arrays, so duplicates of the maximum are common."""


def generate(rng, count):
    return [_case(rng, i + 1) for i in range(count)]


def _case(rng, index):
    n = rng.randint(0, 10)
    values = [rng.randint(-4, 4) for _ in range(n)]
    return {"name": "%d values #%d" % (n, index),
            "stdin": "%d\n%s\n" % (n, " ".join(map(str, values)))}
